-- Resources content for the redesigned legacy-agreement migration (CLAUDE.md,
-- "Resources stay in step with the code"; docs/underwriting-traffic-redesign.md
-- §14.5). Content only — no schema change.

select private.rc_release_guide(
  p_slug => 'underwriting-migrate-legacy-agreements',
  p_tool_key => 'underwriting',
  p_title => 'Migrate legacy agreements',
  p_summary => 'Load a manifest of existing agreements, match each to its signed document, import them as draft contracts, and review the results.',
  p_screen_keys => array['underwriting.migration'],
  p_sort_order => 90,
  p_version_note => 'Rewritten for the step-by-step flow and imports that run three at a time',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Administrators use this screen to bring agreements from the station's legacy records into Underwriting & Traffic. Open it from the Contracts list: "},{"type":"text","text":"Migrate legacy agreements","marks":[{"type":"bold"}]},{"type":"text","text":". It lists every batch with how far along it is and what it needs next."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start a batch"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"New batch","marks":[{"type":"bold"}]},{"type":"text","text":", name the batch, and choose where the facts come from: "},{"type":"text","text":"A spreadsheet of agreements","marks":[{"type":"bold"}]},{"type":"text","text":" (recommended) or "},{"type":"text","text":"Documents only","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For a spreadsheet, choose the manifest CSV or paste its rows. Every row is checked before anything is saved. A row that can't be read, or whose sponsor isn't on file, is listed first. When a close name is on file, select "},{"type":"text","text":"Use it","marks":[{"type":"bold"}]},{"type":"text","text":"; otherwise add the underwriter under Underwriters and load the manifest again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Load and continue","marks":[{"type":"bold"}]},{"type":"text","text":". Rows that still need a fix are left out."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest needs the underwriter and the document's file name in each row; the order number, run dates, sponsorship total, contract type, Drive file id, documentation status, and notes are optional. "},{"type":"text","text":"Download a template","marks":[{"type":"bold"}]},{"type":"text","text":" gives the column names."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose the documents"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose the folder of signed agreements. Each entry is matched to its file by name. Anything that didn't match cleanly is listed under "},{"type":"text","text":"Needs attention","marks":[{"type":"bold"}]},{"type":"text","text":" with what to do: use a close match, choose the file, pick which entry a shared file belongs to, or choose a copy under 10 MB. Files the manifest doesn't name can be imported too, with every fact read from the document."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":". Three agreements are read at a time, each the same way "},{"type":"text","text":"Create from the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" reads a single order, and each takes a minute or two. Keep the page open until the run finishes, or select "},{"type":"text","text":"Stop after the ones reading","marks":[{"type":"bold"}]},{"type":"text","text":". If the reading service asks the portal to slow down, the run pauses and carries on by itself."}]},{"type":"paragraph","content":[{"type":"text","text":"The manifest's facts win over what the document says; the schedule comes from the document. Each entry becomes a draft contract, which schedules nothing until someone activates it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review"}]},{"type":"paragraph","content":[{"type":"text","text":"The batch page opens on "},{"type":"text","text":"Needs a look","marks":[{"type":"bold"}]},{"type":"text","text":": drafts where the document disagrees with the manifest, or where an instruction couldn't be saved as a schedule line. Open a row to see each disagreement side by side, and select "},{"type":"text","text":"Enter on the schedule","marks":[{"type":"bold"}]},{"type":"text","text":" for the lines to enter by hand. "},{"type":"text","text":"Ready to activate","marks":[{"type":"bold"}]},{"type":"text","text":" means nothing was flagged; the draft still needs a look before it's activated. A failed entry shows why; fix the cause and select "},{"type":"text","text":"Run again","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Running it again"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Importing again never creates a second contract for an entry that already has one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loading a corrected manifest under the same batch name updates entries that haven't been imported. Keep each row's key the same."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To redo an imported entry, delete its draft contract; the entry can then be imported again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A document that has already been imported, under any entry, is not imported again."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-30-underwriting-migration-redesign',
  p_tool_key => 'underwriting',
  p_released_on => '2026-09-30',
  p_title => 'A clearer, faster legacy-agreement migration',
  p_guide_slugs => array['underwriting-migrate-legacy-agreements'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Migrating legacy agreements is now a step-by-step flow: a list of batches, a manifest that's checked before it's saved, document matching that says how to fix each problem, and a review page that puts the drafts needing a look first. Agreements are now read three at a time rather than one after another, so a batch finishes much sooner."}]}]}$body$
);
